class Solution {
public:
    void solve(int idx,string curr,vector<string> &ans,string s)
    {
        if(idx==s.size())
        {
            ans.push_back(curr);
            return;
        }
        if(isdigit(s[idx]))
        {
            curr.push_back(s[idx]);
            solve(idx+1,curr,ans,s);
        }
        else
        {
            string now1=curr;
            now1.push_back(tolower(s[idx]));
            solve(idx+1,now1,ans,s);
            string now2=curr;
            now2.push_back(toupper(s[idx]));
            solve(idx+1,now2,ans,s);
        }
    }
    vector<string> letterCasePermutation(string s) {
        vector<string> ans;
        solve(0,"",ans,s);
        return ans;
    }
};

class Solution(object):
    def letterCasePermutation(self, s):
        """
        :type s: str
        :rtype: List[str]
        """
        n = len(s)
        ans = []

        def dfs(cur_str, i):
            if i == n:
                ans.append(cur_str)
                return
            if s[i].isalpha():
                dfs(cur_str + s[i].lower(), i + 1)
                dfs(cur_str + s[i].lower().upper(), i + 1)
            else:
                dfs(cur_str + s[i], i + 1)

        dfs("", 0)
        return ans
